/**
 * @method
 * @name hitbtc#fetchMarkets
 * @description retrieves data on all markets for hitbtc
 * @see https://api.hitbtc.com/#symbols
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Hitbtc) FetchMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Hitbtc) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetPublicSymbol(params)).Raw))
	//
	//     {
	//         "AAVEUSDT_PERP":{
	//             "type":"futures",
	//             "expiry":null,
	//             "underlying":"AAVE",
	//             "base_currency":null,
	//             "quote_currency":"USDT",
	//             "quantity_increment":"0.01",
	//             "tick_size":"0.001",
	//             "take_rate":"0.0005",
	//             "make_rate":"0.0002",
	//             "fee_currency":"USDT",
	//             "margin_trading":true,
	//             "max_initial_leverage":"50.00"
	//         },
	//         "MANAUSDT":{
	//             "type":"spot",
	//             "base_currency":"MANA",
	//             "quote_currency":"USDT",
	//             "quantity_increment":"1",
	//             "tick_size":"0.0000001",
	//             "take_rate":"0.0025",
	//             "make_rate":"0.001",
	//             "fee_currency":"USDT",
	//             "margin_trading":true,
	//             "max_initial_leverage":"5.00"
	//         },
	//     }
	//
	var result []any = []any{}
	var ids []string = ObjectKeys(response)
	for i := 0; i < len(ids); i++ {
		var id string = GetValue(ids, i).(string)
		if strings.HasSuffix(id, "_BQX") {
			continue
		}
		var market map[string]any = SafeMapTyped(response, id)
		var marketType *string = this.SafeString(market, "type")
		var expiry *int64 = this.SafeInteger(market, "expiry")
		var contract bool = (marketType != nil && *marketType == "futures")
		var spot bool = (marketType != nil && *marketType == "spot")
		var marginTrading *bool = this.SafeBool(market, "margin_trading", false)
		var margin bool = spot && (marginTrading != nil && *marginTrading)
		var future bool = (expiry != nil)
		var swap bool = (contract && !future)
		var option bool = false
		var baseId *string = this.SafeString2(market, "base_currency", "underlying")
		var quoteId *string = this.SafeString(market, "quote_currency")
		var feeCurrencyId *string = this.SafeString(market, "fee_currency")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		var feeCurrency *string = this.SafeCurrencyCode(feeCurrencyId)
		var settleId any = nil
		var settle any = nil
		var symbol any = Add(Add(base, "/"), quote)
		var typeVar string = "spot"
		var contractSize any = nil
		var linear any = nil
		var inverse any = nil
		if contract {
			contractSize = this.ParseNumber("1")
			settleId = feeCurrencyId
			settle = DerefScalar(this.SafeCurrencyCode(settleId))
			linear = ((quote != nil) && (IsEqual(quote, settle)))
			inverse = !(linear == true)
			symbol = Add(Add(symbol, ":"), settle)
			if future {
				symbol = Add(Add(symbol, "-"), expiry)
				typeVar = "future"
			} else {
				typeVar = "swap"
			}
		}
		var lotString *string = this.SafeString(market, "quantity_increment")
		var stepString *string = this.SafeString(market, "tick_size")
		var lot *float64 = Float64PtrTyped(this.ParseNumber(lotString))
		var step *float64 = Float64PtrTyped(this.ParseNumber(stepString))
		result = append(result, map[string]any{
			"id":             id,
			"symbol":         symbol,
			"base":           base,
			"quote":          quote,
			"settle":         settle,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       settleId,
			"type":           typeVar,
			"spot":           spot,
			"margin":         margin,
			"swap":           swap,
			"future":         future,
			"option":         option,
			"active":         true,
			"contract":       contract,
			"linear":         linear,
			"inverse":        inverse,
			"taker":          this.SafeNumber(market, "take_rate"),
			"maker":          this.SafeNumber(market, "make_rate"),
			"contractSize":   contractSize,
			"expiry":         expiry,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"feeCurrency":    feeCurrency,
			"precision": map[string]any{
				"amount": lot,
				"price":  step,
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": this.ParseNumber("1"),
					"max": this.SafeNumber(market, "max_initial_leverage", 1),
				},
				"amount": map[string]any{
					"min": lot,
					"max": nil,
				},
				"price": map[string]any{
					"min": step,
					"max": nil,
				},
				"cost": map[string]any{
					"min": this.ParseNumber(Precise.StringMul(lotString, stepString)),
					"max": nil,
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- result
	return nil
}

/**
 * @method
 * @name hitbtc#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://api.hitbtc.com/#currencies
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Hitbtc) FetchCurrenciesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Hitbtc) fetchCurrenciesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PublicGetPublicCurrency(params)).Raw
	PanicOnError(response)
	//
	//    {
	//        "DFC": {
	//            "full_name": "DeFiScale",
	//            "crypto": true,
	//            "payin_enabled": false,
	//            "payout_enabled": true,
	//            "transfer_enabled": false,
	//            "transfer_to_wallet_enabled": true,
	//            "transfer_to_exchange_enabled": false,
	//            "sign": "D",
	//            "crypto_payment_id_name": "",
	//            "crypto_explorer": "https://etherscan.io/tx/{tx}",
	//            "precision_transfer": "0.00000001",
	//            "delisted": false,
	//            "networks": [
	//                {
	//                    "code": "ETH",
	//                    "network_name": "Ethereum",
	//                    "network": "ETH",
	//                    "protocol": "ERC-20",
	//                    "default": true,
	//                    "is_ens_available": true,
	//                    "payin_enabled": true,
	//                    "payout_enabled": true,
	//                    "precision_payout": "0.000000000000000001",
	//                    "payout_fee": "277000.0000000000",
	//                    "payout_is_payment_id": false,
	//                    "payin_payment_id": false,
	//                    "payin_confirmations": "2",
	//                    "contract_address": "0x1b2a76da77d03b7fc21189d9838f55bd849014af",
	//                    "crypto_payment_id_name": "",
	//                    "crypto_explorer": "https://etherscan.io/tx/{tx}",
	//                    "is_multichain": true,
	//                    "asset_id": {
	//                        "contract_address": "0x1b2a76da77d03b7fc21189d9838f55bd849014af"
	//                    }
	//                }
	//            ]
	//        },
	//    }
	//
	var enhancedArray any = this.AddKeyInArrayItems(response, "_coin_id")

	ch <- this.ParseCurrencies(enhancedArray)
	return nil
}
func (this *Hitbtc) ParseCurrency(currency any) any {
	var currencyId any = GetValue(currency, "_coin_id")
	var code *string = this.SafeCurrencyCode(currencyId)
	var entry any = currency
	var rawNetworks []any = SafeListTyped(entry, "networks")
	var networks map[string]any = map[string]any{}
	for j := 0; j < len(rawNetworks); j++ {
		var rawNetwork any = func() any {
			if j >= 0 && j < len(rawNetworks) {
				return DerefScalar(rawNetworks[j])
			}
			return nil
		}()
		var networkId *string = this.SafeString2(rawNetwork, "protocol", "network")
		var networkCode any = DerefScalar(this.NetworkIdToCode(networkId, code))
		networkCode = func() any {
			if networkCode != nil {
				return ToUpper(networkCode)
			}
			return code
		}() // as hitbtc is white label, ensure we safeguard from possible bugs
		if networkCode != nil {
			AddElementToObject(networks, networkCode, map[string]any{
				"info":      rawNetwork,
				"id":        networkId,
				"network":   networkCode,
				"active":    nil,
				"fee":       this.SafeNumber(rawNetwork, "payout_fee"),
				"deposit":   this.SafeBool(rawNetwork, "payin_enabled"),
				"withdraw":  this.SafeBool(rawNetwork, "payout_enabled"),
				"precision": this.SafeNumber(rawNetwork, "precision_payout"),
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": nil,
						"max": nil,
					},
				},
			})
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"info":      entry,
		"code":      code,
		"id":        currencyId,
		"precision": this.SafeNumber(entry, "precision_transfer"),
		"name":      this.SafeString(entry, "full_name"),
		"active":    !IsEqual(this.SafeBool(entry, "delisted"), true),
		"deposit":   this.SafeBool(entry, "payin_enabled"),
		"withdraw":  this.SafeBool(entry, "payout_enabled"),
		"networks":  networks,
		"fee":       nil,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"type": nil,
	})
}

/**
 * @method
 * @name hitbtc#createDepositAddress
 * @description create a currency deposit address
 * @see https://api.hitbtc.com/#generate-deposit-crypto-address
 * @param {string} code unified currency code of the currency for the deposit address
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Hitbtc) CreateDepositAddressAsync(code any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Hitbtc) createDepositAddressBody(ch chan any, code any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = MapTyped(this.Currency(code))
	var request map[string]any = map[string]any{
		"currency": currency["id"],
	}
	var network *string = this.SafeStringUpper(params, "network")
	if (network != nil) && (IsEqual(code, "USDT")) {
		var networks map[string]any = SafeMapTyped(this.Options, "networks")
		var parsedNetwork *string = this.SafeString(networks, network)
		if parsedNetwork != nil {
			request["currency"] = parsedNetwork
		}
		params = MapTyped(this.Omit(params, "network"))
	}

	response := (<-this.PrivatePostWalletCryptoAddress(this.Extend(request, params))).Raw
	PanicOnError(response)
	//
	//  {"currency":"ETH","address":"0xd0d9aea60c41988c3e68417e2616065617b7afd3"}
	//
	var currencyId *string = this.SafeString(response, "currency")

	ch <- map[string]any{
		"currency": this.SafeCurrencyCode(currencyId),
		"address":  this.SafeString(response, "address"),
		"tag":      this.SafeString(response, "payment_id"),
		"network":  nil,
		"info":     response,
	}
	return nil
}

/**
 * @method
 * @name hitbtc#fetchDepositAddress
 * @description fetch the deposit address for a currency associated with this account
 * @see https://api.hitbtc.com/#get-deposit-crypto-address
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Hitbtc) FetchDepositAddressAsync(code any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Hitbtc) fetchDepositAddressBody(ch chan any, code any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = MapTyped(this.Currency(code))
	var request map[string]any = map[string]any{
		"currency": currency["id"],
	}
	var network *string = this.SafeStringUpper(params, "network")
	if (network != nil) && (IsEqual(code, "USDT")) {
		var networks map[string]any = SafeMapTyped(this.Options, "networks")
		var parsedNetwork *string = this.SafeString(networks, network)
		if parsedNetwork != nil {
			request["currency"] = parsedNetwork
		}
		params = MapTyped(this.Omit(params, "network"))
	}

	response := (<-this.PrivateGetWalletCryptoAddress(this.Extend(request, params))).Raw
	PanicOnError(response)
	//
	//  [{"currency":"ETH","address":"0xd0d9aea60c41988c3e68417e2616065617b7afd3"}]
	//
	var firstAddress map[string]any = SafeMapTyped(response, 0)
	var address *string = this.SafeString(firstAddress, "address")
	var currencyId *string = this.SafeString(firstAddress, "currency")
	var tag *string = this.SafeString(firstAddress, "payment_id")
	var parsedCode *string = this.SafeCurrencyCode(currencyId)

	ch <- map[string]any{
		"info":     response,
		"currency": parsedCode,
		"network":  nil,
		"address":  address,
		"tag":      tag,
	}
	return nil
}
func (this *Hitbtc) ParseBalance(response any) any {
	var result map[string]any = map[string]any{
		"info": response,
	}
	for i := 0; i < GetArrayLength(response); i++ {
		var entry map[string]any = SafeMapTyped(response, i)
		var currencyId *string = this.SafeString(entry, "currency")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(entry, "available")
		account["used"] = this.SafeString(entry, "reserved")
		if code != nil {
			AddElementToObject(result, code, account)
		}
	}
	return this.SafeBalance(result)
}

/**
 * @method
 * @name hitbtc#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @see https://api.hitbtc.com/#wallet-balance
 * @see https://api.hitbtc.com/#get-spot-trading-balance
 * @see https://api.hitbtc.com/#get-trading-balance
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Hitbtc) FetchBalanceAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Hitbtc) fetchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var typeVar *string = this.SafeStringLower(params, "type", "spot")
	params = MapTyped(this.Omit(params, []any{"type"}))
	var accountsByType map[string]any = SafeMapTyped(this.Options, "accountsByType")
	var account any = func() any {
		if typeVar == nil {
			return nil
		}
		return this.SafeString(accountsByType, typeVar, typeVar)
	}()
	var response map[string]any = nil
	if IsEqual(account, "wallet") {

		response = MapTyped(PanicOnError((<-this.PrivateGetWalletBalance(params)).Raw))
	} else if IsEqual(account, "spot") {

		response = MapTyped(PanicOnError((<-this.PrivateGetSpotBalance(params)).Raw))
	} else if IsEqual(account, "derivatives") {

		response = MapTyped(PanicOnError((<-this.PrivateGetFuturesBalance(params)).Raw))
	} else {
		var keys []string = ObjectKeys(accountsByType)
		panic(BadRequest(this.Id + " fetchBalance() type parameter must be one of " + strings.Join(keys, ", ")))
	}

	//
	//     [
	//       {
	//         "currency": "PAXG",
	//         "available": "0",
	//         "reserved": "0",
	//         "reserved_margin": "0",
	//       },
	//       ...
	//     ]
	//
	ch <- this.ParseBalance(response)
	return nil
}

