/**
 * @method
 * @name hitbtc#createOrder
 * @description create a trade order
 * @see https://api.hitbtc.com/#create-new-spot-order
 * @see https://api.hitbtc.com/#create-margin-order
 * @see https://api.hitbtc.com/#create-futures-order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.marginMode] 'cross' or 'isolated' only 'isolated' is supported for spot-margin, swap supports both, default is 'cross'
 * @param {bool} [params.margin] true for creating a margin order
 * @param {float} [params.triggerPrice] The price at which a trigger order is triggered at
 * @param {bool} [params.postOnly] if true, the order will only be posted to the order book and not executed immediately
 * @param {string} [params.timeInForce] "GTC", "IOC", "FOK", "Day", "GTD"
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Hitbtc) CreateOrderAsync(symbol any, typeVar any, side any, amount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Hitbtc) createOrderBody(ch chan any, symbol any, typeVar any, side any, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = MapTyped(this.Market(symbol))
	var request any = nil
	var marketType any = nil
	var marketTypeparamsVariable []any = this.HandleMarketTypeAndParams("createOrder", market, params)
	marketType = GetValue(marketTypeparamsVariable, 0)
	params = MapTyped(GetValue(marketTypeparamsVariable, 1))
	var marginMode any = nil
	var marginModeparamsVariable []any = this.HandleMarginModeAndParams("createOrder", params)
	marginMode = GetValue(marginModeparamsVariable, 0)
	params = MapTyped(GetValue(marginModeparamsVariable, 1))
	requestparamsVariable := this.CreateOrderRequest(market, marketType, typeVar, side, amount, price, marginMode, params)
	request = GetValue(requestparamsVariable, 0)
	params = MapTyped(GetValue(requestparamsVariable, 1))
	var response map[string]any = nil
	if IsEqual(marketType, "swap") {

		response = MapTyped(PanicOnError((<-this.PrivatePostFuturesOrder(this.Extend(request, params))).Raw))
	} else if (IsEqual(marketType, "margin")) || (marginMode != nil) {

		response = MapTyped(PanicOnError((<-this.PrivatePostMarginOrder(this.Extend(request, params))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.PrivatePostSpotOrder(this.Extend(request, params))).Raw))
	}

	ch <- this.ParseOrder(response, market)
	return nil
}
func (this *Hitbtc) CreateOrderRequest(market any, marketType any, typeVar any, side any, amount any, optionalArgs ...any) any {
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	marginMode := GetArg(optionalArgs, 1, nil)
	_ = marginMode
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	var isLimit bool = (IsEqual(typeVar, "limit"))
	var reduceOnly *bool = this.SafeBool(params, "reduceOnly")
	var timeInForce *string = this.SafeString(params, "timeInForce")
	var triggerPrice *float64 = this.SafeNumberN(params, []any{"triggerPrice", "stopPrice", "stop_price"})
	var isPostOnly bool = this.IsPostOnly((IsEqual(typeVar, "market")), nil, params)
	var request map[string]any = map[string]any{
		"type":     typeVar,
		"side":     side,
		"quantity": this.AmountToPrecision(GetValue(market, "symbol"), amount),
		"symbol":   GetValue(market, "id"),
	}
	if reduceOnly != nil {
		if (!IsEqual(GetValue(market, "type"), "swap")) && (!IsEqual(GetValue(market, "type"), "margin")) {
			panic(InvalidOrder(Add(Add(this.Id+" createOrder() does not support reduce_only for ", GetValue(market, "type")), " orders, reduce_only orders are supported for swap and margin markets only")))
		}
	}
	if reduceOnly != nil && *reduceOnly == true {
		request["reduce_only"] = reduceOnly
	}
	if isPostOnly {
		request["post_only"] = true
	}
	if timeInForce != nil {
		request["time_in_force"] = timeInForce
	}
	if isLimit || (IsEqual(typeVar, "stopLimit")) || (IsEqual(typeVar, "takeProfitLimit")) {
		if price == nil {
			panic(ExchangeError(this.Id + " createOrder() requires a price argument for limit orders"))
		}
		request["price"] = this.PriceToPrecision(GetValue(market, "symbol"), price)
	}
	if timeInForce != nil && *timeInForce == "GTD" {
		var expireTime *string = this.SafeString(params, "expire_time")
		if expireTime == nil {
			panic(ExchangeError(this.Id + " createOrder() requires an expire_time parameter for a GTD order"))
		}
	}
	if triggerPrice != nil {
		request["stop_price"] = this.PriceToPrecision(GetValue(market, "symbol"), triggerPrice)
		if isLimit {
			request["type"] = "stopLimit"
		} else if IsEqual(typeVar, "market") {
			request["type"] = "stopMarket"
		}
	} else if (IsEqual(typeVar, "stopLimit")) || (IsEqual(typeVar, "stopMarket")) || (IsEqual(typeVar, "takeProfitLimit")) || (IsEqual(typeVar, "takeProfitMarket")) {
		panic(ExchangeError(this.Id + " createOrder() requires a triggerPrice parameter for stop-loss and take-profit orders"))
	}
	params = MapTyped(this.Omit(params, []any{"triggerPrice", "timeInForce", "stopPrice", "stop_price", "reduceOnly", "postOnly"}))
	if IsEqual(marketType, "swap") {
		// set default margin mode to cross
		if marginMode == nil {
			marginMode = "cross"
		}
		request["margin_mode"] = marginMode
	}
	return []any{request, params}
}
func (this *Hitbtc) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"new":             "open",
		"suspended":       "open",
		"partiallyFilled": "open",
		"filled":          "closed",
		"canceled":        "canceled",
		"expired":         "failed",
	}
	if status == nil {
		return nil
	}
	return this.SafeString(statuses, status, status)
}
func (this *Hitbtc) ParseOrder(order any, optionalArgs ...any) any {
	//
	// limit
	//     {
	//       "id": 488953123149,
	//       "client_order_id": "103ad305301e4c3590045b13de15b36e",
	//       "symbol": "BTCUSDT",
	//       "side": "buy",
	//       "status": "new",
	//       "type": "limit",
	//       "time_in_force": "GTC",
	//       "quantity": "0.00001",
	//       "quantity_cumulative": "0",
	//       "price": "0.01",
	//       "price_average": "0.01",
	//       "post_only": false,
	//       "created_at": "2021-04-13T13:06:16.567Z",
	//       "updated_at": "2021-04-13T13:06:16.567Z"
	//     }
	//
	// market
	//     {
	//       "id": "685877626834",
	//       "client_order_id": "Yshl7G-EjaREyXQYaGbsmdtVbW-nzQwu",
	//       "symbol": "BTCUSDT",
	//       "side": "buy",
	//       "status": "filled",
	//       "type": "market",
	//       "time_in_force": "GTC",
	//       "quantity": "0.00010",
	//       "quantity_cumulative": "0.00010",
	//       "post_only": false,
	//       "created_at": "2021-10-26T08:55:55.1Z",
	//       "updated_at": "2021-10-26T08:55:55.1Z",
	//       "trades": [
	//         {
	//           "id": "1437229630",
	//           "position_id": "0",
	//           "quantity": "0.00010",
	//           "price": "62884.78",
	//           "fee": "0.005659630200",
	//           "timestamp": "2021-10-26T08:55:55.1Z",
	//           "taker": true
	//         }
	//       ]
	//     }
	//
	// swap and margin
	//
	//     {
	//         "id": 58418961892,
	//         "client_order_id": "r42gdPjNMZN-H_xs8RKl2wljg_dfgdg4",
	//         "symbol": "BTCUSDT_PERP",
	//         "side": "buy",
	//         "status": "new",
	//         "type": "limit",
	//         "time_in_force": "GTC",
	//         "quantity": "0.0005",
	//         "quantity_cumulative": "0",
	//         "price": "30000.00",
	//         "post_only": false,
	//         "reduce_only": false,
	//         "created_at": "2022-03-16T08:16:53.039Z",
	//         "updated_at": "2022-03-16T08:16:53.039Z"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "client_order_id")
	// we use clientOrderId as the order id with this exchange intentionally
	// because most of their endpoints will require clientOrderId
	// explained here: https://github.com/ccxt/ccxt/issues/5674
	var side *string = this.SafeString(order, "side")
	var typeVar *string = this.SafeString(order, "type")
	var amount *string = this.SafeString(order, "quantity")
	var price *string = this.SafeString(order, "price")
	var average *string = this.SafeString(order, "price_average")
	var created *string = this.SafeString(order, "created_at")
	var timestamp *int64 = this.Parse8601(created)
	var updated *string = this.SafeString(order, "updated_at")
	var lastTradeTimestamp *int64 = nil
	if updated != created && (updated == nil || created == nil || *updated != *created) {
		lastTradeTimestamp = this.Parse8601(updated)
	}
	var filled *string = this.SafeString(order, "quantity_cumulative")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var marketId *string = this.SafeString(order, "symbol")
	market = MapTyped(this.SafeMarket(marketId, market))
	var symbol *string = SafeStringPtr(market["symbol"])
	var postOnly *bool = this.SafeBool(order, "post_only")
	var timeInForce *string = this.SafeString(order, "time_in_force")
	var rawTrades []any = SafeListTyped(order, "trades")
	return this.SafeOrder(map[string]any{
		"info":                order,
		"id":                  id,
		"clientOrderId":       id,
		"timestamp":           timestamp,
		"datetime":            this.Iso8601(timestamp),
		"lastTradeTimestamp":  lastTradeTimestamp,
		"lastUpdateTimestamp": lastTradeTimestamp,
		"symbol":              symbol,
		"price":               price,
		"amount":              amount,
		"type":                typeVar,
		"side":                side,
		"timeInForce":         timeInForce,
		"postOnly":            postOnly,
		"reduceOnly":          this.SafeBool(order, "reduce_only"),
		"filled":              filled,
		"remaining":           nil,
		"cost":                nil,
		"status":              status,
		"average":             average,
		"trades":              rawTrades,
		"fee":                 nil,
		"triggerPrice":        this.SafeString(order, "stop_price"),
		"takeProfitPrice":     nil,
		"stopLossPrice":       nil,
	}, market)
}

/**
 * @method
 * @name hitbtc#fetchMarginModes
 * @description fetches margin mode of the user
 * @see https://api.hitbtc.com/#get-margin-position-parameters
 * @see https://api.hitbtc.com/#get-futures-position-parameters
 * @param {string[]} symbols unified market symbols
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a list of [margin mode structures]{@link https://docs.ccxt.com/?id=margin-mode-structure}
 */
func (this *Hitbtc) FetchMarginModesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarginModesBody(ch, optionalArgs...)
	return ch
}
func (this *Hitbtc) fetchMarginModesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	symbols := GetArg(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = nil
	if symbols != nil {
		symbols = this.MarketSymbols(symbols)
		market = this.Market(GetValue(symbols, 0))
	}
	var marketType *string = nil
	var marketTypeparamsVariable []any = this.HandleMarketTypeAndParams("fetchMarginMode", market, params)
	marketType = SafeStringPtr(GetValue(marketTypeparamsVariable, 0))
	params = MapTyped(GetValue(marketTypeparamsVariable, 1))
	var response map[string]any = nil
	if marketType != nil && *marketType == "margin" {

		response = MapTyped(PanicOnError((<-this.PrivateGetMarginConfig(params)).Raw))
	} else if marketType != nil && *marketType == "swap" {

		response = MapTyped(PanicOnError((<-this.PrivateGetFuturesConfig(params)).Raw))
	} else {
		panic(BadSymbol(this.Id + " fetchMarginModes () supports swap contracts and margin only"))
	}
	var config []any = SafeListTypedDefault(response, "config", []any{})

	ch <- this.ParseMarginModes(config, symbols, "symbol")
	return nil
}
func (this *Hitbtc) ParseMarginMode(marginMode any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(marginMode, "symbol")
	return map[string]any{
		"info":       marginMode,
		"symbol":     this.SafeSymbol(marketId, market),
		"marginMode": this.SafeStringLower(marginMode, "margin_mode"),
	}
}

