func (this *Hitbtc) transferBody(ch chan any, code any, amount any, fromAccount any, toAccount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// account can be "spot", "wallet", or "derivatives"
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = MapTyped(this.Currency(code))
	var requestAmount any = this.CurrencyToPrecision(code, amount)
	var accountsByType map[string]any = SafeMapTyped(this.Options, "accountsByType")
	fromAccount = ToLower(fromAccount)
	toAccount = ToLower(toAccount)
	var fromId *string = this.SafeString(accountsByType, fromAccount, fromAccount)
	var toId *string = this.SafeString(accountsByType, toAccount, toAccount)
	if fromId == toId || (fromId != nil && toId != nil && *fromId == *toId) {
		panic(BadRequest(this.Id + " transfer() fromAccount and toAccount arguments cannot be the same account"))
	}
	var request map[string]any = map[string]any{
		"currency":    currency["id"],
		"amount":      requestAmount,
		"source":      fromId,
		"destination": toId,
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostWalletTransfer(this.Extend(request, params))).Raw))

	//
	//     [
	//         "2db6ebab-fb26-4537-9ef8-1a689472d236"
	//     ]
	//
	ch <- this.ParseTransfer(response, currency)
	return nil
}
