/**
 * @method
 * @name hitbtc#fetchOpenInterests
 * @description Retrieves the open interest for a list of symbols
 * @see https://api.hitbtc.com/#futures-info
 * @param {string[]} [symbols] a list of unified CCXT market symbols
 * @param {object} [params] exchange specific parameters
 * @returns {object[]} a list of [open interest structures]{@link https://docs.ccxt.com/?id=open-interest-structure}
 */
func (this *Hitbtc) FetchOpenInterestsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOpenInterestsBody(ch, optionalArgs...)
	return ch
}
func (this *Hitbtc) fetchOpenInterestsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	symbols := GetArg(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var request map[string]any = map[string]any{}
	symbols = this.MarketSymbols(symbols)
	var marketIds any = nil
	if symbols != nil {
		marketIds = this.MarketIds(symbols)
		request["symbols"] = Join(marketIds, ",")
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetPublicFuturesInfo(this.Extend(request, params))).Raw))
	//
	//     {
	//         "BTCUSDT_PERP": {
	//             "contract_type": "perpetual",
	//             "mark_price": "97291.83",
	//             "index_price": "97298.61",
	//             "funding_rate": "-0.000183473092423284",
	//             "open_interest": "94.1503",
	//             "next_funding_time": "2024-12-20T08:00:00.000Z",
	//             "indicative_funding_rate": "-0.00027495203277752",
	//             "premium_index": "-0.000789474900583786",
	//             "avg_premium_index": "-0.000683473092423284",
	//             "interest_rate": "0.0001",
	//             "timestamp": "2024-12-20T04:57:33.693Z"
	//         }
	//     }
	//
	var results []any = []any{}
	var markets []string = ObjectKeys(response)
	for i := 0; i < len(markets); i++ {
		var marketId string = GetValue(markets, i).(string)
		var marketInner map[string]any = MapTyped(this.SafeMarket(marketId))
		var openInterest map[string]any = MapTyped(this.SafeDict(response, marketId, map[string]any{}))
		results = append(results, this.ParseOpenInterest(openInterest, marketInner))
	}

	ch <- this.FilterByArray(results, "symbol", symbols)
	return nil
}

