	//             }
	//         ],
	//         "positions": [
	//             {
	//                 "id": 631301,
	//                 "symbol": "BTCUSDT",
	//                 "quantity": "0.00022",
	//                 "price_entry": "47425.57",
	//                 "price_margin_call": "",
	//                 "price_liquidation": "0",
	//                 "pnl": "0",
	//                 "created_at": "2022-03-29T22:31:29.067Z",
	//                 "updated_at": "2022-03-30T00:00:00.125Z"
	//             }
	//         ]
	//     }
	//
	ch <- this.ParseLeverage(response, market)
	return nil
