func (this *Hitbtc) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	//
	//    {
	//         "full_name": "ConnectWealth",
	//         "payin_enabled": false,
	//         "payout_enabled": false,
	//         "transfer_enabled": true,
	//         "precision_transfer": "0.001",
	//         "networks": [
	//           {
	//             "network": "ETH",
	//             "protocol": "ERC20",
	//             "default": true,
	//             "payin_enabled": false,
	//             "payout_enabled": false,
	//             "precision_payout": "0.001",
	//             "payout_fee": "0.016800000000",
	//             "payout_is_payment_id": false,
	//             "payin_payment_id": false,
	//             "payin_confirmations": "2"
	//           }
	//         ]
	//    }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var networks []any = SafeListTyped(fee, "networks")
	var result any = this.DepositWithdrawFee(fee)
	for j := 0; j < len(networks); j++ {
		var networkEntry map[string]any = SafeMapTyped(networks, j)
		var networkId *string = this.SafeString(networkEntry, "network")
		var code *string = this.SafeString(currency, "code")
		var networkCode any = DerefScalar(this.NetworkIdToCode(networkId, code))
		networkCode = func() any {
			if networkCode != nil {
				return ToUpper(networkCode)
			}
			return nil
		}()
		var withdrawFee *float64 = this.SafeNumber(networkEntry, "payout_fee")
		var isDefault *bool = this.SafeBool(networkEntry, "default")
		var withdrawResult map[string]any = map[string]any{
			"fee": withdrawFee,
			"percentage": func() any {
				if withdrawFee != nil {
					return false
				}
				return nil
			}(),
		}
		if isDefault != nil && *isDefault == true {
			AddElementToObject(result, "withdraw", withdrawResult)
		}
		if networkCode != nil {
			AddElementToObject(GetValue(result, "networks"), networkCode, map[string]any{
				"withdraw": withdrawResult,
				"deposit": map[string]any{
					"fee":        nil,
					"percentage": nil,
				},
			})
		}
	}
	return result
}

